String _formatCurrency(final double value) {
  if (value == 0) return '₹0';
  if (value >= 10000000) return '₹${(value / 10000000).toStringAsFixed(2)}Cr';
  if (value >= 100000) return '₹${(value / 100000).toStringAsFixed(2)}L';
  return '₹${value.toStringAsFixed(2)}';
}

