void _checkNewsTimestamp() {
  if (_cubit.selectedAssetType != MoGetQuoteAssetType.cash) {
    return;
  }

  final dynamic newsData = _cubit.overviewDataManager.marketUpdatesData;
  if (newsData != null && newsData.items.isNotEmpty) {
    _cachedNewsData = newsData;
    final int newsTime = newsData.items[0].timestamp ?? 0;
    final int now = DateTime.now().millisecondsSinceEpoch;
    final String newsId = newsData.items[0].id.toString();
    final String scripId = newsData.items[0].company.id.scripCode.toString();
    final String? storedNewsId = Preferences.getFlashNewsId(scripId);
    final int timeDifference = (now - (newsTime * 1000));
    // CHANGED: Check if news is within the current day instead of 30 minutes
    final bool isWithinDay = timeDifference < (24 * 60 * 60 * 1000); // 24 hours in milliseconds
    final bool isVisible = isWithinDay && (newsId != storedNewsId);

    setState(() {
      _isBottomContainerVisible = isVisible;
    });
  }
}

